// src/components/hrm/HrmPayroll.tsx
//
// Payroll (PHASE D1) on the EXISTING payroll APIs — no calculation engine
// written here. Runs list + per-run detail (per-employee entries straight
// from HrPayrollEntry) + lifecycle actions. The whole surface rides the
// SENSITIVE gates: reads require hrSalaryView, actions hrSalaryEdit
// (enforced by the payroll routes; this UI is convenience only).
//
// Payslips as standalone documents are a known gap (payslipNumber is never
// generated by the backend) — the run detail view shows the same data
// without pretending to be an issued payslip.

"use client";

import { useMemo, useState } from "react";
import { ChevronLeft, Plus, Download } from "lucide-react";
import { toast } from "sonner";
import {
  useGetPayrollRunsQuery,
  useGetPayrollRunByIdQuery,
  useGetEmployeesQuery,
  useCreatePayrollRunMutation,
  useCalculatePayrollRunMutation,
  useApprovePayrollRunMutation,
  useMarkPayrollRunPaidMutation,
} from "@/features/hrmApi";
import { usePermissions } from "@/hooks/usePermissions";
import { SimpleFormDialog } from "@/othersfeatures/hrm/components/employee360/SimpleFormDialog";

const STATUS_CHIP: Record<string, string> = {
  DRAFT: "hrm-chip-resigned",
  CALCULATED: "hrm-chip-probation",
  REVIEW: "hrm-chip-probation",
  APPROVED: "hrm-chip-active",
  PROCESSING: "hrm-chip-late",
  PAID: "hrm-chip-active",
  CANCELLED: "hrm-chip-absent",
};

const money = (v: unknown) => `৳${Number(v ?? 0).toLocaleString()}`;
const period = (m: number, y: number) =>
  ["", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][m] ?? `#${m}`;

function csvCell(v: unknown): string {
  const s = String(v ?? "");
  return /^[=+\-@]/.test(s) ? `'${s}` : s;
}

export function HrmPayroll() {
  const { can } = usePermissions();
  const canEdit = can("hrSalaryEdit");

  const [selected, setSelected] = useState<string | null>(null);
  const [createOpen, setCreateOpen] = useState(false);

  const runs = useGetPayrollRunsQuery();
  const run = useGetPayrollRunByIdQuery(selected ?? "", { skip: !selected });
  const { data: employees } = useGetEmployeesQuery({ page: 1, limit: 100 });

  const nameOf = useMemo(() => {
    const m: Record<string, string> = {};
    (employees?.items ?? []).forEach((e) => { m[e.id] = e.fullName; });
    return m;
  }, [employees]);

  const [createRun, { isLoading: creating }] = useCreatePayrollRunMutation();
  const [calculate] = useCalculatePayrollRunMutation();
  const [approve] = useApprovePayrollRunMutation();
  const [markPaid] = useMarkPayrollRunPaidMutation();

  async function act(fn: () => Promise<unknown>, message: string) {
    try {
      await fn();
      toast.success(message);
    } catch (err: any) {
      toast.error(err?.data?.message || err?.message || "Action failed.");
    }
  }

  const detail = run.data?.data;

  function exportEntries() {
    if (!detail) return;
    const header = ["Employee", "Basic context", "Gross", "Bonus", "Deductions", "Net", "Status"];
    const lines = (detail.entries ?? []).map((e: any) =>
      [
        nameOf[e.employeeId] ?? e.employeeId,
        `${e.presentDays ?? 0}p/${e.absentDays ?? 0}a/${e.leaveDays ?? 0}l`,
        e.gross, e.bonus,
        Number(e.absenceDeduction ?? 0) + Number(e.loanDeduction ?? 0) + Number(e.advanceDeduction ?? 0) + Number(e.otherDeduction ?? 0),
        e.net, e.status,
      ].map(csvCell).join(",")
    );
    const csv = "\uFEFF" + header.join(",") + "\n" + lines.join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const a = document.createElement("a");
    a.href = url;
    a.download = `payroll-${detail.periodYear}-${String(detail.periodMonth).padStart(2, "0")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  // ── Detail view ──
  if (selected) {
    return (
      <div>
        <button className="hrm-pill" onClick={() => setSelected(null)}>
          <ChevronLeft size={13} /> All runs
        </button>
        <h1 className="hrm-page-title" style={{ marginTop: 12 }}>
          Payroll — {period(detail?.periodMonth ?? 0, detail?.periodYear ?? 0)} {detail?.periodYear}
        </h1>
        <p className="hrm-page-subtitle">
          Per-employee payroll entries as calculated by the existing payroll service
        </p>

        {run.isLoading && <div className="hrm-loading-block" style={{ height: 200 }} />}
        {run.isError && <div className="hrm-card p-6 text-sm text-red-600">Failed to load this run.</div>}

        {detail && (
          <>
            <div className="grid grid-cols-2 gap-4 lg:grid-cols-5">
              {[
                ["Status", <span key="s" className={`hrm-chip ${STATUS_CHIP[detail.status] ?? "hrm-chip-resigned"}`}>{detail.status}</span>],
                ["Employees", detail.employeeCount ?? detail.entries?.length ?? 0],
                ["Gross", money(detail.totalGross)],
                ["Bonus", money(detail.totalBonus)],
                ["Net", money(detail.totalNet)],
              ].map(([label, value], i) => (
                <div key={i} className="hrm-card hrm-stat-card">
                  <div>
                    <p className="hrm-stat-label">{label as string}</p>
                    <p className="hrm-stat-value" style={{ fontSize: 18 }}>{value as React.ReactNode}</p>
                  </div>
                </div>
              ))}
            </div>

            {canEdit && (
              <div className="mt-4 flex flex-wrap gap-2">
                {detail.status === "DRAFT" && (
                  <button className="hrm-pill hrm-pill-active" onClick={() => act(() => calculate(detail.id).unwrap(), "Run calculated.")}>
                    Calculate
                  </button>
                )}
                {detail.status === "CALCULATED" && (
                  <button className="hrm-pill hrm-pill-active" onClick={() => act(() => approve(detail.id).unwrap(), "Run approved.")}>
                    Approve
                  </button>
                )}
                {detail.status === "APPROVED" && (
                  <button className="hrm-pill hrm-pill-active" onClick={() => act(() => markPaid(detail.id).unwrap(), "Run marked paid — loans/advances settled.")}>
                    Mark Paid
                  </button>
                )}
                <button className="hrm-pill" onClick={exportEntries}><Download size={13} /> CSV</button>
              </div>
            )}

            <div className="hrm-card mt-4" style={{ overflow: "hidden" }}>
              <div className="overflow-x-auto">
                <table className="hrm-table">
                  <thead><tr>{["Employee", "Attendance", "Gross", "Bonus", "Deductions", "Net", "Status"].map((h) => <th key={h}>{h}</th>)}</tr></thead>
                  <tbody>
                    {(detail.entries ?? []).length === 0 && (
                      <tr><td colSpan={7} className="p-10 text-center text-sm" style={{ color: "var(--hrm-muted)" }}>
                        No entries yet — calculate the run to build per-employee payroll.
                      </td></tr>
                    )}
                    {(detail.entries ?? []).map((e: any) => {
                      const deductions = Number(e.absenceDeduction ?? 0) + Number(e.loanDeduction ?? 0) + Number(e.advanceDeduction ?? 0) + Number(e.otherDeduction ?? 0);
                      return (
                        <tr key={e.id}>
                          <td style={{ fontWeight: 600, color: "var(--hrm-text)" }}>{nameOf[e.employeeId] ?? `${e.employeeId.slice(0, 8)}…`}</td>
                          <td>{e.presentDays ?? 0}p · {e.absentDays ?? 0}a · {e.leaveDays ?? 0}l</td>
                          <td>{money(e.gross)}</td>
                          <td>{money(e.bonus)}</td>
                          <td>{money(deductions)}</td>
                          <td style={{ fontWeight: 800, color: "#047857" }}>{money(e.net)}</td>
                          <td><span className={`hrm-chip ${STATUS_CHIP[e.status] ?? "hrm-chip-resigned"}`}>{e.status}</span></td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
            <p className="mt-2 text-[11px]" style={{ color: "var(--hrm-muted)" }}>
              Standalone payslip documents (numbered, printable) arrive with the payslip phase —
              this view shows the same underlying entries without issuing documents.
            </p>
          </>
        )}
      </div>
    );
  }

  // ── Runs list ──
  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="hrm-page-title">Payroll</h1>
          <p className="hrm-page-subtitle">Payroll runs — create, calculate, approve and disburse</p>
        </div>
        {canEdit && (
          <button className="hrm-pill hrm-pill-active" onClick={() => setCreateOpen(true)}>
            <Plus size={13} /> New Run
          </button>
        )}
      </div>

      {runs.isLoading && <div className="hrm-loading-block" style={{ height: 200, marginTop: 20 }} />}
      {runs.isError && (
        <div className="hrm-card mt-5 p-6 text-sm text-red-600">
          Failed to load payroll runs — payroll reads require the hrSalaryView capability.
        </div>
      )}

      {runs.data && runs.data.data.length === 0 && (
        <div className="hrm-card mt-5 p-10 text-center text-sm" style={{ color: "var(--hrm-muted)" }}>
          No payroll runs yet. Create a run for a month, then calculate it to build per-employee payroll.
        </div>
      )}

      <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
        {(runs.data?.data ?? []).map((r: any) => (
          <button key={r.id} className="hrm-card p-5 text-left" onClick={() => setSelected(r.id)}>
            <div className="flex items-center justify-between">
              <p style={{ margin: 0, fontSize: 14, fontWeight: 800, color: "var(--hrm-text)" }}>
                {period(r.periodMonth, r.periodYear)} {r.periodYear}
              </p>
              <span className={`hrm-chip ${STATUS_CHIP[r.status] ?? "hrm-chip-resigned"}`}>{r.status}</span>
            </div>
            <div className="mt-3 grid grid-cols-3 gap-2 text-center">
              <div><p className="hrm-stat-label">Gross</p><p style={{ margin: 0, fontSize: 12.5, fontWeight: 700, color: "var(--hrm-text)" }}>{r.totalGross != null ? money(r.totalGross) : "—"}</p></div>
              <div><p className="hrm-stat-label">Net</p><p style={{ margin: 0, fontSize: 12.5, fontWeight: 700, color: "#047857" }}>{r.totalNet != null ? money(r.totalNet) : "—"}</p></div>
              <div><p className="hrm-stat-label">Staff</p><p style={{ margin: 0, fontSize: 12.5, fontWeight: 700, color: "var(--hrm-text)" }}>{r.employeeCount ?? "—"}</p></div>
            </div>
            {r.paymentDate && (
              <p style={{ margin: "8px 0 0", fontSize: 11, color: "var(--hrm-muted)" }}>Paid {r.paymentDate.slice(0, 10)}</p>
            )}
          </button>
        ))}
      </div>

      {createOpen && (
        <SimpleFormDialog
          title="New payroll run"
          fields={[
            { name: "periodMonth", label: "Month", type: "select", required: true,
              options: Array.from({ length: 12 }, (_, i) => ({ value: String(i + 1), label: period(i + 1, 0) })) },
            { name: "periodYear", label: "Year", type: "number", required: true },
          ]}
          initial={{ periodMonth: String(new Date().getMonth() + 1), periodYear: String(new Date().getFullYear()) }}
          loading={creating}
          onSave={async (values: Record<string, unknown>) => {
            try {
              await createRun({
                periodMonth: Number(values.periodMonth),
                periodYear: Number(values.periodYear),
              }).unwrap();
              toast.success("Run created (DRAFT) — calculate it to build entries.");
              setCreateOpen(false);
            } catch (err: any) {
              toast.error(err?.data?.message || "Failed to create run.");
            }
          }}
          onClose={() => setCreateOpen(false)}
        />
      )}
    </div>
  );
}
